#pragma once
#include "kstationFlashStateTask.h"
namespace kstation {
class PanelPublishTask final {
public:
 enum class Stage {RetainPointer,RetainData,BindMirror,BindMux,Count,ReadMirror,WriteData,WriteMux,ClearStrobe,RetainDelay,BindDelay,TickDelay,RepeatDelay,RestoreDelay,SetStrobe,AdvanceMux,DecrementCount,Repeat,ReadFlags,ReadPort,ShiftFirst,CopyFirst,ShiftSecond,CopySecond,WritePort,WriteMirror,RestoreData,RestorePointer,Return,Complete};
 enum class Read {Mirror,Strobe,Flags,Port};enum class Write {Data,Mux,Strobe,Port,Mirror};
 Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}unsigned index()const{return index_;}
 unsigned nextClocks(const FlashCredits&c)const{switch(stage_){case Stage::RetainPointer:case Stage::RetainData:return c.pushLong;case Stage::BindMirror:return 9;case Stage::Count:case Stage::BindDelay:return 6;case Stage::ReadMirror:return 5+c.read;case Stage::WriteData:case Stage::WriteMux:case Stage::WritePort:return 3+c.write;case Stage::ClearStrobe:case Stage::SetStrobe:return 6+c.read+c.write;case Stage::RetainDelay:return c.pushWord;case Stage::RestoreDelay:return c.popWord;case Stage::ReadFlags:return 9+c.read;case Stage::ReadPort:return 3+c.read;case Stage::WriteMirror:return 9+c.write;case Stage::RestoreData:case Stage::RestorePointer:return c.popLong;case Stage::Return:return c.ret;case Stage::Complete:return 0;default:return 3;}}
 template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::BindMux:mux_=0x60;break;case Stage::Count:remaining_=4;break;case Stage::ReadMirror:data_=uint8_t(read(Read::Mirror,index_));break;case Stage::WriteData:write(Write::Data,data_);break;case Stage::WriteMux:write(Write::Mux,mux_);break;case Stage::ClearStrobe:write(Write::Strobe,uint8_t(read(Read::Strobe,0))&0xbf);break;case Stage::BindDelay:delay_=3;break;case Stage::TickDelay:--delay_;break;case Stage::RepeatDelay:if(delay_)next=Stage::TickDelay;break;case Stage::SetStrobe:write(Write::Strobe,uint8_t(read(Read::Strobe,0))|0x40);break;case Stage::AdvanceMux:mux_=uint8_t(mux_+8);++index_;break;case Stage::DecrementCount:--remaining_;break;case Stage::Repeat:if(remaining_)next=Stage::ReadMirror;break;case Stage::ReadFlags:flags_=uint8_t(read(Read::Flags,0));break;case Stage::ReadPort:port_=uint8_t(read(Read::Port,0));break;case Stage::ShiftFirst:case Stage::ShiftSecond:carry_=flags_&1;flags_>>=1;break;case Stage::CopyFirst:port_=uint8_t((port_&~16u)|(carry_?16:0));break;case Stage::CopySecond:port_=uint8_t((port_&~32u)|(carry_?32:0));break;case Stage::WritePort:write(Write::Port,port_);break;case Stage::WriteMirror:write(Write::Mirror,port_);break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::RetainPointer;unsigned index_=0;uint8_t mux_=0,data_=0,remaining_=0,delay_=0,flags_=0,port_=0;bool carry_=false;
};
class PanelBitsTask final {
public:
 enum class Stage {RetainIndex,RetainMask,RetainMirror,RetainInput,CopyIndex,BindScale,Multiply,Extend,BindTable,ReadSet,ReadClear,ReadMirror,ClearBits,DecrementSelection,SelectSelection,Shift,Repeat,Merge,WriteMirror,Publish,RestoreInput,RestoreMirror,RestoreMask,RestoreIndex,Return,Complete};enum class Read{Set,Clear,Mirror};
 PanelBitsTask(uint8_t index=0,uint8_t selection=0):index_(index),selection_(selection){}Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}unsigned index()const{return index_;}
 unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::RetainIndex:case Stage::RetainMask:case Stage::RetainMirror:return c.pushLong;case Stage::RetainInput:return c.pushWord;case Stage::Multiply:return 15;case Stage::ClearBits:case Stage::Merge:return 6;case Stage::BindTable:return 9;case Stage::ReadSet:return 8+c.read;case Stage::ReadClear:return 6+c.read;case Stage::ReadMirror:return 12+c.read;case Stage::WriteMirror:return 12+c.write;case Stage::Publish:return c.call;case Stage::RestoreInput:return c.popWord;case Stage::RestoreMirror:case Stage::RestoreMask:case Stage::RestoreIndex:return c.popLong;case Stage::Return:return c.ret;default:return 3;}}
 template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::ReadSet:set_=read(Read::Set);break;case Stage::ReadClear:clear_=read(Read::Clear);break;case Stage::ReadMirror:mirror_=read(Read::Mirror);break;case Stage::ClearBits:mirror_&=clear_;break;case Stage::DecrementSelection:{int value=int8_t(selection_)-1;negative_=value<0;selection_=uint8_t(value);break;}case Stage::SelectSelection:if(negative_)next=Stage::Merge;break;case Stage::Shift:set_<<=1;break;case Stage::Repeat:next=Stage::DecrementSelection;break;case Stage::Merge:mirror_|=set_;break;case Stage::WriteMirror:write(mirror_);break;case Stage::Publish:waiting_=true;break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::RetainIndex;uint8_t index_,selection_;uint32_t set_=0,clear_=0,mirror_=0;bool negative_=false,waiting_=false;
};
class PanelModeTask final {
public:enum class Stage {Retain,Read,Mask,TestInput,SelectInput,Set,Write,Publish,Restore,Return,Complete};PanelModeTask(uint8_t value=0,bool first=false):value_(value),first_(first){}Stage stage()const{return stage_;}bool first()const{return first_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}
 unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::Retain:return c.pushWord;case Stage::Read:return 9+c.read;case Stage::Write:return 9+c.write;case Stage::Publish:return c.call;case Stage::Restore:return c.popWord;case Stage::Return:return c.ret;default:return 3;}}
 template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::Read:flags_=uint8_t(read());break;case Stage::Mask:flags_&=first_?2:1;break;case Stage::SelectInput:if(!value_)next=Stage::Write;break;case Stage::Set:flags_|=first_?1:2;break;case Stage::Write:write(flags_);break;case Stage::Publish:waiting_=true;break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::Retain;uint8_t value_=0,flags_=0;bool first_=false,waiting_=false;};
class PanelResetTask final {
public:enum class Stage {Count,Clear,WriteBits,Advance,Decrement,Repeat,WriteMode,WriteFirst,ClearCount,WriteFirstCount,WriteSecondCount,WriteNoticeCount,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}
 unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::WriteBits:case Stage::WriteMode:case Stage::WriteFirst:return c.call;case Stage::WriteFirstCount:case Stage::WriteSecondCount:case Stage::WriteNoticeCount:return 9+c.write;case Stage::Return:return c.ret;default:return 3;}}
 template<class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::Count:remaining_=9;break;case Stage::WriteBits:case Stage::WriteMode:case Stage::WriteFirst:waiting_=true;break;case Stage::Decrement:--remaining_;break;case Stage::Repeat:if(remaining_)next=Stage::WriteBits;break;case Stage::WriteFirstCount:write(0,0);break;case Stage::WriteSecondCount:write(1,0);break;case Stage::WriteNoticeCount:write(2,0);break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::Count;uint8_t remaining_=0;bool waiting_=false;};
}
